package ledger

// Refactoring log
//
// The original implementation passed the test suite but was hard to follow.
// Three unrelated concerns were tangled together inside FormatLedger:
//
//  1. Validation was scattered across three places: a recursive call to
//     FormatLedger for the empty-ledger case (to validate the currency), the
//     header builder (to validate the locale), and the per-entry goroutines
//     (to validate the currency and the date).
//  2. Sorting was a hand-rolled selection sort that encoded the comparison of
//     three fields into a single integer using two lookup maps.
//  3. Formatting launched one goroutine per entry and collected the results
//     over a channel, which bought no real parallelism (the work is trivial
//     string building) while making the code much harder to reason about.
//
// The rewrite keeps the observable behaviour identical but restructures the
// code into small, single-purpose helpers:
//
//   - `locales` and `currencySymbols` tables describe how each locale/currency
//     renders dates and amounts, replacing the scattered if/else chains.
//   - Validation (currency, locale, date) happens once, up front.
//   - `sort.Slice` replaces the hand-rolled selection sort.
//   - Formatting is a plain sequential loop over small helpers (`parseDate`,
//     `formatDate`, `truncate`, `formatAmount`, `padLeft`/`padRight`).
//
// Steps taken, each kept green against the existing test suite:
//
//  1. Extracted the two locales into a `locale` table and the two currencies
//     into a `currencySymbols` table.
//  2. Centralised validation of currency, locale and date at the top of
//     `FormatLedger`, removing the recursive empty-ledger workaround.
//  3. Replaced the selection sort with `sort.Slice` over a copy of the input
//     (the input slice is still never mutated).
//  4. Replaced the goroutine/channel fan-out with a sequential loop.
//  5. Pulled amount formatting into `formatUSAmount`/`formatDutchAmount` with
//     shared `splitCents` and `formatThousands` helpers.
//  6. Pulled date parsing/formatting and description truncation/padding into
//     small helpers, using rune-aware widths so multi-byte characters (e.g.
//     "€") are measured correctly.

import (
	"errors"
	"sort"
	"strconv"
	"strings"
)

// Entry is a single line item in the ledger.
type Entry struct {
	Date        string // "YYYY-MM-DD"
	Description string
	Change      int // in cents
}

// Column widths and the separator used between columns.
const (
	dateWidth        = 10
	descriptionWidth = 25
	changeWidth      = 13
	separator        = " | "
)

// locale describes how a given locale renders the header, dates and amounts.
type locale struct {
	header       [3]string // date, description, change column titles
	formatDate   func(year, month, day string) string
	formatAmount func(symbol string, cents int) string
}

var locales = map[string]locale{
	"en-US": {
		header: [3]string{"Date", "Description", "Change"},
		formatDate: func(year, month, day string) string {
			return month + "/" + day + "/" + year
		},
		formatAmount: formatUSAmount,
	},
	"nl-NL": {
		header: [3]string{"Datum", "Omschrijving", "Verandering"},
		formatDate: func(year, month, day string) string {
			return day + "-" + month + "-" + year
		},
		formatAmount: formatDutchAmount,
	},
}

var currencySymbols = map[string]string{
	"USD": "$",
	"EUR": "€",
}

// FormatLedger renders a formatted ledger for the given currency and locale.
// It does not modify the entries it is given.
func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	loc, ok := locales[locale]
	if !ok {
		return "", errors.New("invalid locale")
	}
	symbol, ok := currencySymbols[currency]
	if !ok {
		return "", errors.New("invalid currency")
	}

	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		if sorted[i].Date != sorted[j].Date {
			return sorted[i].Date < sorted[j].Date
		}
		if sorted[i].Description != sorted[j].Description {
			return sorted[i].Description < sorted[j].Description
		}
		return sorted[i].Change < sorted[j].Change
	})

	var b strings.Builder
	b.WriteString(padRight(loc.header[0], dateWidth))
	b.WriteString(separator)
	b.WriteString(padRight(loc.header[1], descriptionWidth))
	b.WriteString(separator)
	b.WriteString(loc.header[2])
	b.WriteByte('\n')

	for _, entry := range sorted {
		line, err := formatLine(loc, symbol, entry)
		if err != nil {
			return "", err
		}
		b.WriteString(line)
	}
	return b.String(), nil
}

// formatLine renders a single ledger row.
func formatLine(loc locale, symbol string, entry Entry) (string, error) {
	year, month, day, err := parseDate(entry.Date)
	if err != nil {
		return "", err
	}
	return padRight(loc.formatDate(year, month, day), dateWidth) + separator +
		truncate(entry.Description, descriptionWidth) + separator +
		padLeft(loc.formatAmount(symbol, entry.Change), changeWidth) + "\n"
}

// parseDate splits a "YYYY-MM-DD" date, validating its shape.
func parseDate(date string) (year, month, day string, err error) {
	if len(date) != 10 || date[4] != '-' || date[7] != '-' {
		return "", "", "", errors.New("invalid date")
	}
	return date[0:4], date[5:7], date[8:10], nil
}

// formatUSAmount renders a US-locale amount, e.g. "$1,234.56" or "($1,234.56)".
func formatUSAmount(symbol string, cents int) string {
	negative := cents < 0
	if negative {
		cents = -cents
	}
	intPart, centPart := splitCents(cents)
	body := symbol + formatThousands(intPart, ",") + "." + centPart
	if negative {
		return "(" + body + ")"
	}
	return body + " "
}

// formatDutchAmount renders a Dutch-locale amount, e.g. "€ 1.234,56" or "$ 123,45-".
func formatDutchAmount(symbol string, cents int) string {
	negative := cents < 0
	if negative {
		cents = -cents
	}
	intPart, centPart := splitCents(cents)
	body := symbol + " " + formatThousands(intPart, ".") + "," + centPart
	if negative {
		return body + "-"
	}
	return body + " "
}

// splitCents splits a cent amount into its integer part and two-digit cent part.
func splitCents(cents int) (intPart, centPart string) {
	centPart = strconv.Itoa(cents % 100)
	if len(centPart) == 1 {
		centPart = "0" + centPart
	}
	intPart = strconv.Itoa(cents / 100)
	return intPart, centPart
}

// formatThousands inserts sep between groups of three digits, e.g. "1234567"
// becomes "1,234,567" with sep=",".
func formatThousands(s, sep string) string {
	if len(s) <= 3 {
		return s
	}
	lead := len(s) % 3
	if lead == 0 {
		lead = 3
	}
	var b strings.Builder
	b.WriteString(s[:lead])
	for i := lead; i < len(s); i += 3 {
		b.WriteString(sep)
		b.WriteString(s[i : i+3])
	}
	return b.String()
}

// truncate pads s to width, or shortens it to width with a "..." suffix.
func truncate(s string, width int) string {
	runes := []rune(s)
	if len(runes) <= width {
		return padRight(s, width)
	}
	return string(runes[:width-3]) + "..."
}

// padRight pads s on the right with spaces to reach width runes.
func padRight(s string, width int) string {
	if runes := len([]rune(s)); runes < width {
		return s + strings.Repeat(" ", width-runes)
	}
	return s
}

// padLeft pads s on the left with spaces to reach width runes.
func padLeft(s string, width int) string {
	if runes := len([]rune(s)); runes < width {
		return strings.Repeat(" ", width-runes) + s
	}
	return s
}
